/** 14px brand icon for a detected stack; renders nothing for unknown stacks. */
export function StackIcon({ stack }: { stack: string | null | undefined }): React.JSX.Element | null {
	if (!stack) return null;
	const icon = STACKS[stack];
	if (!icon) return null;
	return (
		<svg
			viewBox="0 0 24 24"
			className="size-3.5 shrink-0"
			fill={icon.color ?? "currentColor"}
			aria-label={stack}
			role="img"
		>
			<path d={icon.path} />
		</svg>
	);
}

/**
 * The row's leading icon, guaranteed to fill the column so names stay aligned:
 * a recognised brand mark for the item's stack, else a per-kind fallback glyph
 * (project → server, cli → terminal, brew/docker → their brand). With no kind
 * (Detected listeners) it falls back to a neutral box.
 */
export function RowIcon({
	stack,
	kind,
	runMode,
}: {
	stack?: string | null;
	kind?: ItemKind;
	runMode?: RunMode;
}): React.JSX.Element {
	if (stack && STACKS[stack]) return <StackIcon stack={stack} />;
	if (kind === 'docker') return <StackIcon stack="docker" />;
	if (kind === 'brew') return <StackIcon stack="homebrew" />;
	const Fallback =
		kind === 'project'
			? Server
			: kind === 'command'
				? Waypoints
				: kind === 'cli'
					? runMode === 'terminal'
						? SquareTerminal
						: Terminal
					: Box;
	return <Fallback className="size-3.5 shrink-0 text-muted-foreground" aria-hidden />;
}
